/* â”€â”€ Parent Chat Cards ("kind of conversations") â”€â”€â”€â”€â”€â”€â”€â”€ */
.fp-chat-card {
  background: #0f172a;
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 16px;
  padding: 1.75rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  transition: all 0.4s cubic-bezier(0.165, 0.84, 0.44, 1);
  box-shadow: 0 8px 28px rgba(0,0,0,.25);
  position: relative;
  overflow: hidden;
}
.fp-chat-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 18px 44px rgba(0,0,0,.35);
  border-color: rgba(255,255,255,0.14);
}
/* Geometric accent shape (top-right corner) */
.fp-chat-card::after {
  content: '';
  position: absolute;
  top: -20px;
  right: -20px;
  width: 100px;
  height: 100px;
  border-radius: 50%;
  background: rgba(255,255,255,0.04);
  pointer-events: none;
}
.fp-chat-card::before {
  content: '';
  position: absolute;
  bottom: -30px;
  right: -10px;
  width: 80px;
  height: 80px;
  border: 2px solid rgba(255,255,255,0.06);
  border-radius: 50%;
  pointer-events: none;
}
.fp-chat-header {
  display: flex; align-items: center; gap: 0.75rem;
  padding-bottom: 0.85rem;
  border-bottom: 1px solid rgba(255,255,255,0.08);
  position: relative;
  z-index: 1;
}
.fp-chat-avatar {
  width: 38px; height: 38px; border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  font-family: 'Nunito', sans-serif;
  font-weight: 800;
  font-size: 0.78rem;
  color: white;
  flex-shrink: 0;
}
.fp-chat-meta__name {
  font-family: 'Nunito', sans-serif;
  font-size: 0.88rem;
  font-weight: 800;
  color: rgba(255,255,255,0.95);
}
.fp-chat-meta__channel {
  font-family: 'DM Sans', sans-serif;
  font-size: 0.67rem;
  color: rgba(255,255,255,0.4);
  letter-spacing: 0.02em;
}
.fp-chat-bubbles {
  display: flex; flex-direction: column; gap: 0.65rem;
  position: relative;
  z-index: 1;
}
.fp-bubble {
  font-family: 'DM Sans', sans-serif;
  font-size: 0.82rem;
  line-height: 1.55;
  padding: 0.7rem 0.9rem;
  max-width: 88%;
}
.fp-bubble--incoming {
  background: rgba(255,255,255,0.07);
  color: rgba(255,255,255,0.82);
  border-radius: 0 12px 12px 12px;
}
.fp-bubble--outgoing {
  background: rgba(244,96,12,0.18);
  color: rgba(255,200,160,0.95);
  border-radius: 12px 0 12px 12px;
  align-self: flex-end;
  text-align: right;
}
.fp-chat-verified {
  display: flex; align-items: center; gap: 0.4rem;
  border-top: 1px solid rgba(255,255,255,0.07);
  padding-top: 0.75rem;
  margin-top: auto;
  position: relative;
  z-index: 1;
}
.fp-chat-verified span {
  font-family: 'DM Sans', sans-serif;
  font-size: 0.65rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #34d399;
}

